import { useEffect, useMemo, useRef, useState } from 'react'
import { createRoot } from 'react-dom/client'
import './styles.css'
import { supabase } from './lib/supabase'

type Page = 'Dashboard' | 'Privacy Policies' | 'Consents' | 'Audit Logs' | 'Retention Policies' | 'Data Requests' | 'My Privacy' | 'SME Customer App'
type Toast = { text: string; kind: 'success' | 'error' } | null
type RequestRow = { id?: string; user: string; type: string; date: string; status: string; userId?: string }
type RetentionRow = { id?: string; dataType: string; period: string; action: string; status: string }
type ConsentAdminRow = { id: string; user: string; policy: string; version: string; status: string; date: string }

const nav: { label: Page; icon: string; admin?: boolean }[] = [
  { label: 'Dashboard', icon: '▦', admin: true }, { label: 'Privacy Policies', icon: '▤' },
  { label: 'Consents', icon: '✓', admin: true }, { label: 'Audit Logs', icon: '◷', admin: true },
  { label: 'Retention Policies', icon: '▣', admin: true }, { label: 'Data Requests', icon: '↗', admin: true },
  { label: 'My Privacy', icon: '◉' }, { label: 'SME Customer App', icon: '♙', admin: true },
]
