function Badge({ children }: { children: string }) { return <span className={`badge ${children.toLowerCase().replace(' ', '-')}`}>{children}</span> }
function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`card ${className}`}>{children}</section> }
function ActionButton({ children, onClick, secondary = false }: { children: React.ReactNode; onClick?: () => void; secondary?: boolean }) { return <button onClick={onClick} className={secondary ? 'button secondary' : 'button'}>{children}</button> }
function LogoMark() { return <div className="brand-mark" aria-label="DataGuard logo"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M16 3.5 25 7v7.2c0 6-3.8 10.9-9 13.1-5.2-2.2-9-7.1-9-13.1V7l9-3.5Z" fill="currentColor" opacity=".26"/><path d="M16 4.8 23.7 7.8v6.4c0 5.1-3.1 9.4-7.7 11.5-4.6-2.1-7.7-6.4-7.7-11.5V7.8L16 4.8Z" stroke="currentColor" strokeWidth="2" strokeLinejoin="round"/><path d="m12.2 15.8 2.3 2.3 5.4-5.5" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"/><circle cx="23.8" cy="7.3" r="2.2" fill="#A675D9"/></svg></div> }
function BellIcon() { return <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg> }
function MenuIcon() { return <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round"/></svg> }

function App({ userId, userName = 'Anna Becker', userEmail = '', initialIsAdmin = false, onLogout }: { userId?: string; userName?: string; userEmail?: string; initialIsAdmin?: boolean; onLogout?: () => void }) {
  const [page, setPage] = useState<Page>('Dashboard')
  const [isAdmin, setIsAdmin] = useState(initialIsAdmin)
  const [policyRows, setPolicyRows] = useState<any[]>(policies)
  const [policyForm, setPolicyForm] = useState<{ id?: string; title: string; version: string; effectiveDate: string; content: string } | null>(null)
  const [policyVersionForm, setPolicyVersionForm] = useState<{ policyId: string; title: string; version: string; effectiveDate: string; content: string } | null>(null)
  const [policyViewer, setPolicyViewer] = useState<{ title: string; version: string; content: string } | null>(null)
  const [consent, setConsent] = useState(true)
  const [consentInfo, setConsentInfo] = useState<{ status: 'accepted' | 'withdrawn'; decidedAt?: string } | null>(null)
  const [toast, setToast] = useState<Toast>(null)
  const [hasNotification, setHasNotification] = useState(true)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)
  const [audit, setAudit] = useState(logs)
  const [auditAction, setAuditAction] = useState('All actions')
  const [auditDate, setAuditDate] = useState('')
  const [requests, setRequests] = useState<RequestRow[]>([])
  const [retention, setRetention] = useState<RetentionRow[]>([{ dataType: 'Customer Data', period: '2 years', action: 'Delete', status: 'Active' }, { dataType: 'Audit Logs', period: '1 year', action: 'Archive', status: 'Active' }, { dataType: 'Consent Records', period: '3 years', action: 'Keep', status: 'Active' }])
  const [retentionForm, setRetentionForm] = useState<{ id?: string; dataType: string; period: string; action: string; status: string } | null>(null)
  const [retentionResult, setRetentionResult] = useState<string | null>(null)
  const [adminConsents, setAdminConsents] = useState<ConsentAdminRow[]>([])
  const [dashboardStats, setDashboardStats] = useState({ users: '0', consents: '0', policies: '0', requests: '0' })
  const [consentStats, setConsentStats] = useState({ accepted: 0, rejected: 0, withdrawn: 0 })
  const [customerRows, setCustomerRows] = useState(customers)
  const [customerForm, setCustomerForm] = useState<{ id?: string; name: string; email: string; phone: string; address: string } | null>(null)
  const [customerViewer, setCustomerViewer] = useState<{ name: string; email: string; phone: string; address: string } | null>(null)
  const [profileMenu, setProfileMenu] = useState(false)
  const notify = (text: string, kind: 'success' | 'error' = 'success') => { setToast({ text, kind }); window.setTimeout(() => setToast(null), 3200) }
  const logAction = async (action: string, resource: string) => {
    setAudit(a => [[new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short' }) + ', now', userName, action, resource, 'Success'], ...a])
    if (!supabase || !userId) return
    const { error } = await supabase.from('audit_logs').insert({ actor_id: userId, action, resource, status: 'Success' })
    if (error) { console.warn('Audit log was not saved:', error.message); return }
    if (isAdmin) await loadAudit()
  }
  const loadAudit = async () => { if (!supabase || !isAdmin) return; const { data, error } = await supabase.from('audit_logs').select('id,actor_id,action,resource,status,created_at').order('created_at', { ascending: false }); if (error || !data || data.length === 0) return; const actorIds = [...new Set(data.map(log => log.actor_id).filter(Boolean))] as string[]; const { data: profileData } = actorIds.length ? await supabase.from('profiles').select('id,full_name').in('id', actorIds) : { data: [] }; const names = new Map((profileData || []).map(profile => [profile.id, profile.full_name])); setAudit(data.map(log => [new Date(log.created_at).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }), log.actor_id ? names.get(log.actor_id) || 'User' : 'System', log.action, log.resource, log.status])) }
  useEffect(() => { void loadAudit() }, [isAdmin])
  const availableNav = useMemo(() => nav.filter(item => isAdmin || !item.admin), [isAdmin])
  const loadRequests = async () => { if (!supabase) return; const { data, error } = await supabase.from('data_requests').select('id,user_id,type,status,requested_at').order('requested_at', { ascending: false }); if (error || !data) return; const ids = [...new Set(data.map(r => r.user_id))]; const { data: profileData } = ids.length ? await supabase.from('profiles').select('id,full_name').in('id', ids) : { data: [] }; const names = new Map((profileData || []).map(p => [p.id, p.full_name])); setRequests(data.map(r => ({ id: r.id, userId: r.user_id, user: names.get(r.user_id) || 'User', type: r.type === 'data_export' ? 'Data Export' : 'Data Deletion', date: new Date(r.requested_at).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }), status: r.status.charAt(0).toUpperCase() + r.status.slice(1) }))) }
  useEffect(() => { void loadRequests() }, [])
  const makeRequest = async (type: 'Data Export' | 'Data Deletion') => {
    const existing = requests.some(r => r.userId === userId && r.type === type && (r.status === 'Pending' || r.status === 'Approved'))
    if (existing) { notify(`You already have a ${type.toLowerCase()} request in progress`, 'error'); return }
    if (supabase && userId) {
      const { error } = await supabase.from('data_requests').insert({ user_id: userId, type: type === 'Data Export' ? 'data_export' : 'data_deletion' })
      if (error) { notify(error.message, 'error'); return }
      await loadRequests()
      void logAction('CREATE', `${type} request`)
      notify(`${type} request submitted for administrator review`)
      return
    }
    setRequests(r => [{ user: userName, type, date: new Date().toLocaleDateString('en-GB'), status: 'Pending', userId }, ...r])
    void logAction('CREATE', `${type} request`)
    notify(`${type} request submitted`)
  }
  const updateRequest = async (request: RequestRow, status: 'Approved' | 'Rejected') => { if (!supabase || !request.id || !userId) { notify('This request needs to be saved first', 'error'); return } const { error } = await supabase.from('data_requests').update({ status: status.toLowerCase(), reviewed_by: userId, reviewed_at: new Date().toISOString() }).eq('id', request.id); if (error) { notify(error.message, 'error'); return } await Promise.all([loadRequests(), loadDashboardStats()]); void logAction('UPDATE', `${request.type} request: ${status}`); notify(`Request ${status.toLowerCase()}`) }
  const completeRequest = async (request: RequestRow) => { if (!supabase || !request.id || !userId) return; const { error } = await supabase.from('data_requests').update({ status: 'completed', reviewed_by: userId, reviewed_at: new Date().toISOString() }).eq('id', request.id); if (error) { notify(error.message, 'error'); return } await Promise.all([loadRequests(), loadDashboardStats()]); void logAction(request.type === 'Data Export' ? 'EXPORT' : 'DELETE', `${request.type} request completed`); notify(request.type === 'Data Export' ? 'Data export completed - the user can now download it' : 'Deletion request marked as completed') }
  const loadRetention = async () => { if (!supabase) return; const { data, error } = await supabase.from('retention_policies').select('id,data_type,retention_period,action,status').order('created_at', { ascending: true }); if (!error && data && data.length > 0) setRetention(data.map(r => ({ id: r.id, dataType: r.data_type, period: r.retention_period, action: r.action, status: r.status }))) }
  useEffect(() => { void loadRetention() }, [])
  const saveRetention = async () => { if (!retentionForm?.dataType.trim() || !retentionForm.period.trim()) { notify('Data type and retention period are required'); return } if (!supabase) return; if (retentionForm.id) { const { error } = await supabase.from('retention_policies').update({ data_type: retentionForm.dataType.trim(), retention_period: retentionForm.period.trim(), action: retentionForm.action, status: retentionForm.status }).eq('id', retentionForm.id); if (error) { notify(error.message); return } logAction('UPDATE', `Retention policy: ${retentionForm.dataType}`); notify('Retention policy updated') } else { const { error } = await supabase.from('retention_policies').insert({ data_type: retentionForm.dataType.trim(), retention_period: retentionForm.period.trim(), action: retentionForm.action, status: retentionForm.status }); if (error) { notify(error.message); return } logAction('CREATE', `Retention policy: ${retentionForm.dataType}`); notify('Retention policy saved') } setRetentionForm(null); await loadRetention() }
  const processRetention = async () => {
    const activeRules = retention.filter(rule => rule.status === 'Active').length
    setRetentionResult(`Manual review completed: ${activeRules} active retention policies were reviewed. No customer records were automatically deleted in this prototype.`)
    await logAction('UPDATE', `Retention review: ${activeRules} active policies`)
    notify('Retention review processed and logged')
  }
  const loadAdminConsents = async () => { if (!supabase || !isAdmin) return; const { data, error } = await supabase.from('consents').select('id,user_id,policy_version_id,status,decided_at').order('decided_at', { ascending: false }); if (error || !data) return; const userIds = [...new Set(data.map(row => row.user_id))]; const versionIds = [...new Set(data.map(row => row.policy_version_id))]; const [{ data: profiles }, { data: versions }] = await Promise.all([supabase.from('profiles').select('id,full_name').in('id', userIds), supabase.from('policy_versions').select('id,version,policy_id').in('id', versionIds)]); const policyIds = [...new Set((versions || []).map(v => v.policy_id))]; const { data: policyData } = policyIds.length ? await supabase.from('privacy_policies').select('id,title').in('id', policyIds) : { data: [] }; const names = new Map((profiles || []).map(p => [p.id, p.full_name])); const versionMap = new Map((versions || []).map(v => [v.id, v])); const titles = new Map((policyData || []).map(p => [p.id, p.title])); setAdminConsents(data.map(row => { const version = versionMap.get(row.policy_version_id); return { id: row.id, user: names.get(row.user_id) || 'User', policy: titles.get(version?.policy_id || '') || 'Privacy Policy', version: version?.version || '—', status: row.status.charAt(0).toUpperCase() + row.status.slice(1), date: new Date(row.decided_at).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) } })) }
  useEffect(() => { void loadAdminConsents() }, [isAdmin])
  const loadDashboardStats = async () => { if (!supabase || !isAdmin) return; const [users, consentRows, policyCount, pending] = await Promise.all([supabase.from('profiles').select('*', { count: 'exact', head: true }), supabase.from('consents').select('user_id,policy_version_id,status,decided_at').order('decided_at', { ascending: false }), supabase.from('privacy_policies').select('*', { count: 'exact', head: true }), supabase.from('data_requests').select('*', { count: 'exact', head: true }).eq('status', 'pending')]); const latestConsents = new Map<string, string>(); for (const row of consentRows.data || []) { const key = `${row.user_id}-${row.policy_version_id}`; if (!latestConsents.has(key)) latestConsents.set(key, row.status) } const statuses = [...latestConsents.values()]; const accepted = statuses.filter(status => status === 'accepted').length; setDashboardStats({ users: String(users.count || 0), consents: String(accepted), policies: String(policyCount.count || 0), requests: String(pending.count || 0) }); setConsentStats({ accepted, rejected: statuses.filter(status => status === 'rejected').length, withdrawn: statuses.filter(status => status === 'withdrawn').length }) }
  useEffect(() => { void loadDashboardStats() }, [isAdmin])
  useEffect(() => { if (!isAdmin && page === 'Dashboard') setPage('My Privacy') }, [isAdmin, page])
  const loadPolicies = async () => { if (!supabase) return; const { data, error } = await supabase.from('privacy_policies').select('id,title,status,created_at,updated_at,policy_versions(id,version,content,effective_date,created_at)').order('created_at', { ascending: false }); if (error || !data || data.length === 0) return; setPolicyRows(data.map((p: any) => { const versions = [...(p.policy_versions || [])].sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()); const last = versions[versions.length - 1]; return { id: p.id, versionId: last?.id, title: p.title, version: last?.version || '1.0', content: last?.content || '', status: p.status.charAt(0).toUpperCase() + p.status.slice(1), effective: last?.effective_date ? new Date(last.effective_date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '—', updated: new Date(p.updated_at).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }), history: versions.map((v: any) => v.version) } })) }
  useEffect(() => { void loadPolicies() }, [])
  const createPolicy = async () => { if (!policyForm?.title.trim() || !policyForm.version.trim() || !policyForm.content.trim()) { notify('Title, version and policy text are required', 'error'); return } if (!supabase || !userId) { notify('Supabase is not connected', 'error'); return } if (policyForm.id) { const { error } = await supabase.from('privacy_policies').update({ title: policyForm.title.trim(), updated_at: new Date().toISOString() }).eq('id', policyForm.id); if (error) { notify(error.message, 'error'); return } void logAction('UPDATE', policyForm.title); notify('Policy updated') } else { const { data: policy, error } = await supabase.from('privacy_policies').insert({ title: policyForm.title.trim(), status: 'draft', created_by: userId }).select('id').single(); if (error || !policy) { notify(error?.message || 'Could not create policy', 'error'); return } const { error: versionError } = await supabase.from('policy_versions').insert({ policy_id: policy.id, version: policyForm.version.trim(), content: policyForm.content.trim(), effective_date: policyForm.effectiveDate || new Date().toISOString().slice(0, 10) }); if (versionError) { notify(versionError.message, 'error'); return } const { error: archiveError } = await supabase.from('privacy_policies').update({ status: 'archived', updated_at: new Date().toISOString() }).eq('status', 'current'); if (archiveError) { notify(archiveError.message, 'error'); return } const { error: activateError } = await supabase.from('privacy_policies').update({ status: 'current', updated_at: new Date().toISOString() }).eq('id', policy.id); if (activateError) { notify(activateError.message, 'error'); return } void logAction('CREATE', `${policyForm.title} v${policyForm.version}`); notify('New current policy created; older current policies were archived') } setPolicyForm(null); await Promise.all([loadPolicies(), loadDashboardStats()]) }
  const addPolicyVersion = async () => { if (!policyVersionForm?.version.trim() || !policyVersionForm.content.trim() || !supabase) { notify('Version number and policy text are required', 'error'); return } const { error } = await supabase.from('policy_versions').insert({ policy_id: policyVersionForm.policyId, version: policyVersionForm.version.trim(), content: policyVersionForm.content.trim(), effective_date: policyVersionForm.effectiveDate }); if (error) { notify(error.message, 'error'); return } void logAction('CREATE', `${policyVersionForm.title} v${policyVersionForm.version}`); setPolicyVersionForm(null); await Promise.all([loadPolicies(), loadDashboardStats()]); notify('New policy version saved') }
  const editPolicy = (policy: any) => setPolicyForm({ id: policy.id, title: policy.title, version: policy.version, effectiveDate: new Date().toISOString().slice(0, 10), content: policy.content || '' })
  const deletePolicy = async (policy: any) => {
    if (!policy.id) { notify('Only saved policies can be deleted', 'error'); return }
    if (policy.status === 'Current') { notify('The current policy cannot be deleted. Create another current policy first.', 'error'); return }
    if (!window.confirm(`Delete "${policy.title}" and its version history? This cannot be undone.`)) return
    if (!supabase) return
    const { error } = await supabase.from('privacy_policies').delete().eq('id', policy.id)
    if (error) { notify('This policy cannot be deleted because it is linked to saved consent records. Keep it archived instead.', 'error'); return }
    void logAction('DELETE', `Privacy policy: ${policy.title}`)
    await Promise.all([loadPolicies(), loadDashboardStats()])
    notify('Archived policy deleted')
  }
  const loadCustomers = async () => { if (!supabase) return; const { data, error } = await supabase.from('customers').select('id,name,email,phone,address').order('created_at', { ascending: false }); if (!error && data && data.length > 0) setCustomerRows(data.map(c => ({ id: c.id, name: c.name, email: c.email, phone: c.phone || '—', address: c.address || '—' }))) }
  useEffect(() => { void loadCustomers() }, [])
  const addCustomer = async () => { if (!customerForm?.name.trim() || !customerForm.email.trim()) { notify('Name and email are required'); return } if (!supabase) return; if (customerForm.id) { const { error } = await supabase.from('customers').update({ name: customerForm.name.trim(), email: customerForm.email.trim(), phone: customerForm.phone, address: customerForm.address, updated_at: new Date().toISOString() }).eq('id', customerForm.id); if (error) { notify(error.message); return } logAction('UPDATE', `Customer: ${customerForm.name}`); notify('Customer updated') } else { const { error } = await supabase.from('customers').insert({ name: customerForm.name.trim(), email: customerForm.email.trim(), phone: customerForm.phone, address: customerForm.address }); if (error) { notify(error.message); return } logAction('CREATE', `Customer: ${customerForm.name}`); notify('Customer saved') } setCustomerForm(null); await loadCustomers() }
  const editCustomer = (customer: typeof customerRows[number]) => { if (customer.id.startsWith('demo-')) { notify('Create a saved customer first to edit database data'); return } setCustomerForm({ id: customer.id, name: customer.name, email: customer.email, phone: customer.phone === '—' ? '' : customer.phone, address: customer.address === '—' ? '' : customer.address }) }
  const deleteCustomer = async (customer: typeof customerRows[number]) => { if (!window.confirm(`Delete ${customer.name}?`)) return; if (!supabase || customer.id.startsWith('demo-')) { setCustomerRows(rows => rows.filter(c => c.id !== customer.id)); logAction('DELETE', `Customer: ${customer.name}`); notify('Demo customer removed'); return } const { error } = await supabase.from('customers').delete().eq('id', customer.id); if (error) { notify(error.message); return } setCustomerRows(rows => rows.filter(c => c.id !== customer.id)); logAction('DELETE', `Customer: ${customer.name}`); notify('Customer deleted') }
  const policyCurrent = policyRows.find(policy => policy.status === 'Current') || policyRows[0] || policies[0]
  useEffect(() => { const loadConsent = async () => { if (!supabase || !userId || !policyCurrent?.versionId) return; const { data } = await supabase.from('consents').select('status,decided_at').eq('user_id', userId).eq('policy_version_id', policyCurrent.versionId).order('decided_at', { ascending: false }).limit(1); if (data?.[0]) { setConsent(data[0].status === 'accepted'); setConsentInfo({ status: data[0].status as 'accepted' | 'withdrawn', decidedAt: data[0].decided_at }) } else { setConsent(false); setConsentInfo(null) } }; void loadConsent() }, [userId, policyCurrent?.versionId])
  const changeConsent = async () => { const next = consent ? 'withdrawn' : 'accepted'; if (!supabase || !userId || !policyCurrent?.versionId) { notify('Create a Privacy Policy first', 'error'); return } const decidedAt = new Date().toISOString(); const { error } = await supabase.from('consents').insert({ user_id: userId, policy_version_id: policyCurrent.versionId, status: next }); if (error) { notify(error.message, 'error'); return } setConsent(!consent); setConsentInfo({ status: next, decidedAt }); await loadDashboardStats(); void logAction('CONSENT', `${policyCurrent.title} v${policyCurrent.version}`); notify(next === 'accepted' ? 'Consent accepted and saved' : 'Consent withdrawn and saved') }
  const downloadMyData = async () => { if (!supabase || !userId) return; const [profile, consentData, requestData] = await Promise.all([supabase.from('profiles').select('full_name,role,created_at').eq('id', userId).single(), supabase.from('consents').select('status,decided_at,policy_version_id').eq('user_id', userId), supabase.from('data_requests').select('type,status,requested_at').eq('user_id', userId)]); const exportData = { exportedAt: new Date().toISOString(), profile: profile.data, consents: consentData.data || [], dataRequests: requestData.data || [] }; const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'dataguard-my-data-export.json'; link.click(); URL.revokeObjectURL(url); void logAction('EXPORT', 'My personal data downloaded'); notify('Your JSON data export was downloaded') }

  const consentTotal = consentStats.accepted + consentStats.rejected + consentStats.withdrawn
  const consentRate = consentTotal ? Math.round((consentStats.accepted / consentTotal) * 100) : 0
  const nextVersion = (version: string) => { const [major = '1', minor = '0'] = version.split('.'); return `${Number(major)}.${Number(minor) + 1}` }
  const dashboard = <>
    <div className="page-heading"><div><p className="eyebrow">PRIVACY MANAGEMENT MODULE</p><h1>Privacy Dashboard</h1><p>Welcome back, {userName}. Here’s your privacy overview.</p></div><ActionButton onClick={() => { logAction('EXPORT', 'Privacy report'); notify('Privacy report prepared') }}>↓ Export Report</ActionButton></div>
    <div className="stat-grid">{[[dashboardStats.users, 'Total Users', 'Registered accounts', 'users'], [dashboardStats.consents, 'Active Consents', 'Accepted consents', 'check'], [dashboardStats.policies, 'Privacy Policies', 'Saved policy records', 'files'], [dashboardStats.requests, 'Pending Data Requests', 'Awaiting review', 'requests']].map(([value, label, hint, icon]) => <Card key={label}><div className="stat"><div><p className="stat-value">{value}</p><p className="stat-label">{label}</p></div><div className={`stat-icon ${icon}`}>{icon === 'users' ? '♙' : icon === 'check' ? '✓' : icon === 'files' ? '▤' : '↗'}</div></div><p className="hint">{hint}</p></Card>)}</div>
    <div className="dashboard-grid"><Card><div className="card-title"><div><h2>Recent Audit Activity</h2><p>Latest actions in your workspace</p></div><button className="link" onClick={() => setPage('Audit Logs')}>View all</button></div><div className="activity">{audit.length ? audit.slice(0, 4).map((l, i) => <div className="activity-row" key={i}><div className="activity-dot">{l[2] === 'CONSENT' ? '✓' : '•'}</div><div><strong>{l[1]}</strong> <span>{l[2].toLowerCase()}d {l[3]}</span><small>{l[0]}</small></div><Badge>{l[4]}</Badge></div>) : <p className="empty-state">No audit activity recorded yet. Perform an admin action to create the first entry.</p>}</div></Card><Card><div className="card-title"><div><h2>Consent Statistics</h2><p>Live values from saved consent decisions</p></div></div><div className="donut-wrap"><div className="donut"><span>{consentRate}%</span></div><div className="legend"><p><i className="dot accepted" />Accepted <b>{consentStats.accepted}</b></p><p><i className="dot rejected" />Rejected <b>{consentStats.rejected}</b></p><p><i className="dot withdrawn" />Withdrawn <b>{consentStats.withdrawn}</b></p></div></div></Card></div>
  </>
  const policyPage = <>
    <Header title="Privacy Policies" description={isAdmin ? 'Manage the current policy and keep a readable version history.' : 'Read the current privacy policy and its version history.'} action={isAdmin ? '+ Create Policy' : undefined} onAction={isAdmin ? () => setPolicyForm({ title: 'Customer Privacy Policy', version: '1.0', effectiveDate: new Date().toISOString().slice(0, 10), content: '' }) : undefined} />
    {isAdmin && policyForm && <Card className="customer-form"><div className="card-title"><div><h2>{policyForm.id ? 'Edit Privacy Policy' : 'Create Privacy Policy'}</h2><p>{policyForm.id ? 'Update the policy title.' : 'The new policy becomes Current and existing Current policies are archived.'}</p></div><button className="link" onClick={() => setPolicyForm(null)}>Cancel</button></div><div className="form-grid"><label>Policy title<input value={policyForm.title} onChange={e => setPolicyForm({ ...policyForm, title: e.target.value })} placeholder="Customer Privacy Policy" /></label><label>Version<input disabled={Boolean(policyForm.id)} value={policyForm.version} onChange={e => setPolicyForm({ ...policyForm, version: e.target.value })} placeholder="1.0" /></label><label>Effective date<input disabled={Boolean(policyForm.id)} type="date" value={policyForm.effectiveDate} onChange={e => setPolicyForm({ ...policyForm, effectiveDate: e.target.value })} /></label><label className="wide-field">Policy text<textarea disabled={Boolean(policyForm.id)} value={policyForm.content} onChange={e => setPolicyForm({ ...policyForm, content: e.target.value })} placeholder="Explain what data is collected, why it is used, how long it is retained and how a customer can make a request." /></label></div><ActionButton onClick={() => void createPolicy()}>{policyForm.id ? 'Save Changes' : 'Save Policy'}</ActionButton></Card>}
    {isAdmin && policyVersionForm && <Card className="customer-form"><div className="card-title"><div><h2>New Version: {policyVersionForm.title}</h2><p>Previous versions remain visible in the policy history.</p></div><button className="link" onClick={() => setPolicyVersionForm(null)}>Cancel</button></div><div className="form-grid"><label>New version<input value={policyVersionForm.version} onChange={e => setPolicyVersionForm({ ...policyVersionForm, version: e.target.value })} /></label><label>Effective date<input type="date" value={policyVersionForm.effectiveDate} onChange={e => setPolicyVersionForm({ ...policyVersionForm, effectiveDate: e.target.value })} /></label><label className="wide-field">Policy text<textarea value={policyVersionForm.content} onChange={e => setPolicyVersionForm({ ...policyVersionForm, content: e.target.value })} placeholder="Describe the updated privacy policy version." /></label></div><ActionButton onClick={() => void addPolicyVersion()}>Save New Version</ActionButton></Card>}
    {policyViewer && <Card className="customer-form"><div className="card-title"><div><h2>{policyViewer.title} <span className="version">v{policyViewer.version}</span></h2><p>Saved policy text</p></div><button className="link" onClick={() => setPolicyViewer(null)}>Close</button></div><p className="policy-text">{policyViewer.content || 'No policy text was entered for this version.'}</p></Card>}
    <Card><table><thead><tr><th>Policy</th><th>Current Version</th><th>Status</th><th>Effective Date</th><th>Last Updated</th><th>Actions</th></tr></thead><tbody>{policyRows.map(p => <tr key={p.id || p.title}><td><strong>{p.title}</strong><small>Version history: {p.history.map((v: string) => `v${v}`).join(' · ')}</small></td><td>v{p.version}</td><td><Badge>{p.status}</Badge></td><td>{p.effective}</td><td>{p.updated}</td><td className="table-actions"><button onClick={() => setPolicyViewer({ title: p.title, version: p.version, content: p.content || '' })}>View</button>{isAdmin && <><button onClick={() => editPolicy(p)}>Edit</button><button onClick={() => p.id ? setPolicyVersionForm({ policyId: p.id, title: p.title, version: nextVersion(p.version || '1.0'), effectiveDate: new Date().toISOString().slice(0, 10), content: '' }) : notify('Create a saved policy first', 'error')}>New version</button>{p.status !== 'Current' && <button className="danger-link" onClick={() => void deletePolicy(p)}>Delete</button>}</>}</td></tr>)}</tbody></table></Card>
  </>
  const consentsPage = <><Header title="Consent Management" description="Track customer consent decisions by policy version."/><Card><table><thead><tr>{['User', 'Policy', 'Version', 'Status', 'Date'].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{(adminConsents.length ? adminConsents : consentRows.map((r, i) => ({ id: String(i), user: r[0], policy: r[1], version: r[2], status: r[3], date: r[4] }))).map(row => <tr key={row.id}><td>{row.user}</td><td>{row.policy}</td><td>v{row.version}</td><td><Badge>{row.status}</Badge></td><td>{row.date}</td></tr>)}</tbody></table></Card></>
  const visibleAudit = audit.filter(row => (auditAction === 'All actions' || row[2] === auditAction) && (!auditDate || row[0].includes(new Date(`${auditDate}T00:00:00`).toLocaleDateString('en-GB', { day: '2-digit', month: 'short' }))))
  const auditPage = <><Header title="Audit Logs" description="A simple, searchable record of important privacy actions."/><Card><div className="filters"><select value={auditAction} onChange={e => setAuditAction(e.target.value)}><option>All actions</option><option>LOGIN</option><option>VIEW</option><option>CREATE</option><option>UPDATE</option><option>DELETE</option><option>CONSENT</option><option>EXPORT</option></select><input type="date" value={auditDate} onChange={e => setAuditDate(e.target.value)} aria-label="Filter by date" /><button className="button secondary" onClick={() => { setAuditAction('All actions'); setAuditDate('') }}>Clear filters</button></div><table><thead><tr>{['Date', 'User', 'Action', 'Resource', 'Status'].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{visibleAudit.map((r, i) => <tr key={i}>{r.map((c, j) => <td key={j}>{j === 2 || j === 4 ? <Badge>{c}</Badge> : c}</td>)}</tr>)}</tbody></table></Card></>
  const retentionPage = <><Header title="Retention Policies" description="Define how long customer information is kept." action="+ Add Policy" onAction={() => setRetentionForm({ dataType: '', period: '2 years', action: 'Delete', status: 'Active' })} />{retentionForm && <Card className="customer-form"><div className="card-title"><div><h2>{retentionForm.id ? 'Edit Retention Policy' : 'Add Retention Policy'}</h2><p>Set how long this type of data should be retained.</p></div><button className="link" onClick={() => setRetentionForm(null)}>Cancel</button></div><div className="form-grid"><label>Data type<input value={retentionForm.dataType} onChange={e => setRetentionForm({ ...retentionForm, dataType: e.target.value })} placeholder="Customer Data" /></label><label>Retention period<input value={retentionForm.period} onChange={e => setRetentionForm({ ...retentionForm, period: e.target.value })} placeholder="2 years" /></label><label>Action<select value={retentionForm.action} onChange={e => setRetentionForm({ ...retentionForm, action: e.target.value })}><option>Delete</option><option>Archive</option><option>Keep</option></select></label><label>Status<select value={retentionForm.status} onChange={e => setRetentionForm({ ...retentionForm, status: e.target.value })}><option>Active</option><option>Inactive</option></select></label></div><ActionButton onClick={() => void saveRetention()}>{retentionForm.id ? 'Save Changes' : 'Save Policy'}</ActionButton></Card>}<Card><div className="retention-top"><p>Retention processing is manual: the administrator reviews rules before any action is taken.</p><ActionButton secondary onClick={() => void processRetention()}>Process Retention</ActionButton></div>{retentionResult && <div className="retention-result"><strong>Review result</strong><span>{retentionResult}</span></div>}<table><thead><tr>{['Data Type', 'Retention Period', 'Action', 'Status', ''].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{retention.map((r, i) => <tr key={r.id || i}><td>{r.dataType}</td><td>{r.period}</td><td>{r.action}</td><td><Badge>{r.status}</Badge></td><td><button className="link" onClick={() => r.id ? setRetentionForm({ id: r.id, dataType: r.dataType, period: r.period, action: r.action, status: r.status }) : notify('Create a saved policy first', 'error')}>Edit</button></td></tr>)}</tbody></table></Card></>
  const dataRequests = <><Header title="Data Requests" description="Review customer data export and deletion requests."/><Card>{requests.length ? <table><thead><tr>{['User', 'Request Type', 'Date', 'Status', 'Action'].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{requests.map((r, i) => <tr key={r.id || i}><td>{r.user}</td><td>{r.type}</td><td>{r.date}</td><td><Badge>{r.status}</Badge></td><td>{r.status === 'Pending' && <div className="table-actions"><button onClick={() => void updateRequest(r, 'Approved')}>Approve</button><button className="danger-link" onClick={() => void updateRequest(r, 'Rejected')}>Reject</button></div>}{r.status === 'Approved' && <button className="link" onClick={() => void completeRequest(r)}>Mark completed</button>}{r.status === 'Completed' && <span className="muted">Processed</span>}{r.status === 'Rejected' && <span className="muted">No action needed</span>}</td></tr>)}</tbody></table> : <p className="empty-state">No data requests have been submitted yet.</p>}</Card></>
  const myRequests = requests.filter(request => request.userId === userId)
  const completedExportReady = myRequests.some(request => request.type === 'Data Export' && request.status === 'Completed')
  const completedDeletion = myRequests.some(request => request.type === 'Data Deletion' && request.status === 'Completed')
  const consentDate = consentInfo?.decidedAt ? new Date(consentInfo.decidedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : null
  const myPrivacy = <><Header title="My Privacy" description="Review and control how the SME application uses your personal information."/><div className="privacy-stack"><Card><p className="eyebrow">PRIVACY POLICY</p><h2>{policyCurrent.title} <span className="version">v{policyCurrent.version}</span></h2><p className="muted">Effective {policyCurrent.effective}. This policy explains how the SME application collects and uses your data.</p><button className="link" onClick={() => { setPolicyViewer({ title: policyCurrent.title, version: policyCurrent.version, content: policyCurrent.content || '' }); setPage('Privacy Policies') }}>Read current policy →</button></Card><Card><p className="eyebrow">MY CONSENT</p><div className="consent-status"><div className={`status-ring ${consent ? 'on' : ''}`}>{consent ? '✓' : '!'}</div><div><h2>{consent ? 'Consent active' : 'Consent not active'}</h2><p className="muted">{consent ? `You accepted ${policyCurrent.title} v${policyCurrent.version}.` : 'Accept the current Privacy Policy to activate consent.'}</p></div></div>{consentInfo && <div className="consent-history"><span>Accepted version <strong>v{policyCurrent.version}</strong></span><span>{consentDate ? `Last decision: ${consentDate}` : 'Decision saved'}</span><Badge>{consentInfo.status === 'accepted' ? 'Accepted' : 'Withdrawn'}</Badge></div>}<ActionButton onClick={() => void changeConsent()}>{consent ? 'Withdraw Consent' : 'Accept Privacy Policy'}</ActionButton></Card><Card><p className="eyebrow">MY DATA</p><h2>Your data requests</h2><p className="muted">Request a copy of your data or ask the administrator to delete it. Requests are reviewed before completion.</p><div className="button-row"><ActionButton secondary onClick={() => void makeRequest('Data Export')}>Request My Data</ActionButton><ActionButton secondary onClick={() => void makeRequest('Data Deletion')}>Request Data Deletion</ActionButton>{completedExportReady && <ActionButton onClick={() => void downloadMyData()}>↓ Download completed export</ActionButton>}</div>{myRequests.length ? <div className="request-summary">{myRequests.map(request => <p key={request.id || `${request.type}-${request.date}`}><strong>{request.type}</strong><span>{request.date}</span><Badge>{request.status}</Badge></p>)}</div> : <p className="empty-state">You have not submitted a data request yet.</p>}{completedDeletion && <div className="request-complete"><strong>Deletion request completed</strong><span>Your deletion request has been completed. The administrator has completed the manual review.</span></div>}</Card></div></>
  const customerPage = <><Header title="GlowBeauty Customer App" description="A simple client directory for GlowBeauty, demonstrating privacy controls in an SME app." action="+ Add Customer" onAction={() => setCustomerForm({ name: '', email: '', phone: '', address: '' })} />{customerForm && <Card className="customer-form"><div className="card-title"><div><h2>{customerForm.id ? 'Edit Customer' : 'Add Customer'}</h2><p>Enter GlowBeauty client information for the SME demonstration.</p></div><button className="link" onClick={() => setCustomerForm(null)}>Cancel</button></div><div className="form-grid"><label>Name<input value={customerForm.name} onChange={e => setCustomerForm({ ...customerForm, name: e.target.value })} placeholder="Full name" /></label><label>Email<input type="email" value={customerForm.email} onChange={e => setCustomerForm({ ...customerForm, email: e.target.value })} placeholder="name@example.com" /></label><label>Phone<input value={customerForm.phone} onChange={e => setCustomerForm({ ...customerForm, phone: e.target.value })} placeholder="+383..." /></label><label>Address<input value={customerForm.address} onChange={e => setCustomerForm({ ...customerForm, address: e.target.value })} placeholder="Street, city" /></label></div><ActionButton onClick={() => void addCustomer()}>{customerForm.id ? 'Save Changes' : 'Save Customer'}</ActionButton></Card>}{customerViewer && <Card className="customer-viewer"><div className="card-title"><div><p className="eyebrow">CUSTOMER RECORD</p><h2>{customerViewer.name}</h2><p>Customer details accessed by an administrator and recorded in Audit Logs.</p></div><button className="link" onClick={() => setCustomerViewer(null)}>Close</button></div><div className="customer-details"><div><span>Email address</span><strong>{customerViewer.email}</strong></div><div><span>Phone number</span><strong>{customerViewer.phone}</strong></div><div><span>Address</span><strong>{customerViewer.address}</strong></div><div><span>Privacy control</span><strong>Governed by active retention policies</strong></div></div></Card>}<Card><div className="customer-note"><span>◉</span> GlowBeauty client data is logged and governed by the active retention policies.</div><table><thead><tr>{['Name', 'Email', 'Phone', 'Address', 'Actions'].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{customerRows.map(r => <tr key={r.id}><td>{r.name}</td><td>{r.email}</td><td>{r.phone}</td><td>{r.address}</td><td className="table-actions"><button onClick={() => { setCustomerViewer(r); void logAction('VIEW', `Customer: ${r.name}`); notify(`Customer record opened: ${r.name}`) }}>View</button><button onClick={() => editCustomer(r)}>Edit</button><button className="danger-link" onClick={() => void deleteCustomer(r)}>Delete</button></td></tr>)}</tbody></table></Card></>
  const render = () => ({ 'Dashboard': dashboard, 'Privacy Policies': policyPage, 'Consents': consentsPage, 'Audit Logs': auditPage, 'Retention Policies': retentionPage, 'Data Requests': dataRequests, 'My Privacy': myPrivacy, 'SME Customer App': customerPage }[page])
  const initials = userName.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase()
  const navigate = (nextPage: Page) => { setPage(nextPage); setProfileMenu(false); setNotificationsOpen(false); setMobileNavOpen(false) }
  return <div className="app"><aside><div className="brand"><LogoMark /><span>DataGuard</span></div><p className="workspace">WORKSPACE</p><nav>{availableNav.map(item => <button className={page === item.label ? 'active' : ''} onClick={() => navigate(item.label)} key={item.label}><i>{item.icon}</i>{item.label}</button>)}</nav><div className="sidebar-bottom">{profileMenu && <div className="account-menu"><div className="account-header"><div className="account-avatar">{initials}</div><div><p>MY ACCOUNT</p><strong>{userName}</strong><small>{userEmail || 'Supabase account'}</small></div></div><div className="account-details"><span><i>●</i> Session active</span><span><i>◆</i> {isAdmin ? 'Administrator access' : 'Standard user access'}</span></div><button className="close-account" onClick={() => setProfileMenu(false)}>Close</button><button className="logout-account" onClick={onLogout}>Logout</button></div>}<div className="profile profile-trigger" role="button" tabIndex={0} onClick={() => setProfileMenu(!profileMenu)} onKeyDown={e => { if (e.key === 'Enter') setProfileMenu(!profileMenu) }}><div>{initials}</div><p><b>{userName}</b><small>{isAdmin ? 'Administrator' : 'User'}</small></p><span className="profile-chevron">⌃</span></div></div></aside>{mobileNavOpen && <div className="mobile-nav-backdrop" onClick={() => setMobileNavOpen(false)}><nav className="mobile-nav" aria-label="Mobile navigation" onClick={event => event.stopPropagation()}><div className="mobile-nav-head"><div><LogoMark /><strong>DataGuard</strong></div><button aria-label="Close navigation" onClick={() => setMobileNavOpen(false)}>×</button></div><p>WORKSPACE</p>{availableNav.map(item => <button className={page === item.label ? 'active' : ''} onClick={() => navigate(item.label)} key={item.label}><i>{item.icon}</i>{item.label}</button>)}<div className="mobile-nav-user"><div>{initials}</div><span><strong>{userName}</strong><small>{isAdmin ? 'Administrator' : 'User'}</small></span><button onClick={onLogout}>Logout</button></div></nav></div>}<main onClick={() => { setProfileMenu(false); setNotificationsOpen(false); setMobileNavOpen(false) }}><div className="topbar"><button className="mobile-menu" aria-label="Open navigation" onClick={event => { event.stopPropagation(); setMobileNavOpen(true) }}><MenuIcon /></button><span className="mobile-brand">DataGuard</span><div className="top-right"><span className="environment"><i />LIVE DATABASE</span><div className="notification-wrap"><button className="bell" aria-label="Notifications" title="Notifications" onClick={event => { event.stopPropagation(); setHasNotification(false); setNotificationsOpen(open => !open) }}><BellIcon />{hasNotification && <i />}</button>{notificationsOpen && <div className="notification-panel" onClick={event => event.stopPropagation()}><div className="notification-heading"><div><p>NOTIFICATIONS</p><strong>Activity updates</strong></div><button onClick={() => { setHasNotification(false); setNotificationsOpen(false) }}>Mark all read</button></div>{audit.length ? audit.slice(0, 3).map((entry, index) => <div className="notification-item" key={`${entry[0]}-${index}`}><span>{entry[2] === 'CONSENT' ? '✓' : '•'}</span><div><strong>{entry[2]} · {entry[3]}</strong><small>{entry[0]}</small></div></div>) : <p className="notification-empty">No new activity yet. Important actions will appear here.</p>}</div>}</div></div></div><div className="content">{render()}</div></main>{toast && <div className={`toast ${toast.kind}`}>{toast.kind === 'success' ? '✓' : '!'} {toast.text}</div>}</div>
}
function Header({ title, description, action, onAction }: { title: string; description: string; action?: string; onAction?: () => void }) { return <div className="page-heading"><div><p className="eyebrow">PRIVACY MANAGEMENT</p><h1>{title}</h1><p>{description}</p></div>{action && <ActionButton onClick={onAction}>{action}</ActionButton>}</div> }
function AuthScreen() {
  const [signUp, setSignUp] = useState(false)
  const [forgotPassword, setForgotPassword] = useState(false)
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event: React.FormEvent) => {
    event.preventDefault()
    if (!supabase) return
    setBusy(true); setMessage('')
    if (forgotPassword) {
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}?reset=password` })
      setBusy(false)
      setMessage(error ? error.message : 'Password reset email sent. Check your inbox for the secure link.')
      return
    }
    const result = signUp
      ? await supabase.auth.signUp({ email, password, options: { data: { full_name: name } } })
      : await supabase.auth.signInWithPassword({ email, password })
    setBusy(false)
    if (result.error) setMessage(result.error.message)
    else if (signUp) setMessage('Account created. Check your email to confirm your account, then sign in.')
  }
  return <div className="auth-page"><div className="auth-card"><div className="auth-brand"><LogoMark />DataGuard</div><p className="eyebrow">PRIVACY MANAGEMENT MODULE</p><h1>{forgotPassword ? 'Forgot your password?' : signUp ? 'Create your account' : 'Welcome back'}</h1><p className="auth-copy">{forgotPassword ? 'Enter your email and we will send a secure link to reset your password.' : signUp ? 'Create an account to manage your privacy preferences and data requests.' : 'Sign in to access your privacy workspace.'}</p><form onSubmit={submit}>{signUp && !forgotPassword && <label>Full name<input required value={name} onChange={e => setName(e.target.value)} placeholder="Full name" /></label>}<label>Email address<input required type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="name@example.com" /></label>{!forgotPassword && <label>Password<input required minLength={6} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 6 characters" /></label>}{message && <p className="auth-message">{message}</p>}<button className="button auth-submit" disabled={busy}>{busy ? 'Please wait…' : forgotPassword ? 'Send reset link' : signUp ? 'Create account' : 'Sign in'}</button></form>{!signUp && !forgotPassword && <button className="forgot-password" onClick={() => { setForgotPassword(true); setMessage('') }}>Forgot your password?</button>}<p className="auth-toggle">{forgotPassword ? 'Remember your password?' : signUp ? 'Already have an account?' : 'New to DataGuard?'} <button onClick={() => { if (forgotPassword) setForgotPassword(false); else setSignUp(!signUp); setMessage('') }}>{forgotPassword ? 'Back to sign in' : signUp ? 'Sign in' : 'Create account'}</button></p></div></div>
}
function ResetPasswordScreen({ onComplete }: { onComplete: () => void }) {
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event: React.FormEvent) => {
    event.preventDefault()
    if (password.length < 6) { setMessage('Password must contain at least 6 characters.'); return }
    if (password !== confirmPassword) { setMessage('Passwords do not match.'); return }
    if (!supabase) return
    setBusy(true)
    const { error } = await supabase.auth.updateUser({ password })
    setBusy(false)
    if (error) { setMessage(error.message); return }
    window.history.replaceState({}, document.title, window.location.pathname)
    onComplete()
  }
  return <div className="auth-page"><div className="auth-card"><div className="auth-brand"><LogoMark />DataGuard</div><p className="eyebrow">PASSWORD RECOVERY</p><h1>Set a new password</h1><p className="auth-copy">Choose a new password for your DataGuard account.</p><form onSubmit={submit}><label>New password<input required minLength={6} type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 6 characters" /></label><label>Confirm new password<input required minLength={6} type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Enter the password again" /></label>{message && <p className="auth-message">{message}</p>}<button className="button auth-submit" disabled={busy}>{busy ? 'Saving…' : 'Save new password'}</button></form></div></div>
}
function AppRoot() {
  const [ready, setReady] = useState(!supabase)
  const [user, setUser] = useState<{ id: string; name: string; email: string; admin: boolean } | null>(null)
  const [passwordRecovery, setPasswordRecovery] = useState(false)
  const loggedSessionRef = useRef<string | null>(null)
  useEffect(() => {
    if (!supabase) return
    const client = supabase
    if (window.location.hash.includes('type=recovery') || window.location.search.includes('type=recovery') || window.location.search.includes('reset=password')) setPasswordRecovery(true)
    const load = async () => { const { data: { session } } = await client.auth.getSession(); if (session) { const { data } = await client.from('profiles').select('full_name, role').eq('id', session.user.id).single(); setUser({ id: session.user.id, name: data?.full_name || session.user.email?.split('@')[0] || 'User', email: session.user.email || '', admin: data?.role === 'admin' }); } setReady(true) }
    load()
    const { data: listener } = client.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') { setPasswordRecovery(true); void load(); return }
      if (!session) { setUser(null); loggedSessionRef.current = null; return }
      if (event === 'SIGNED_IN' && loggedSessionRef.current !== session.access_token) {
        loggedSessionRef.current = session.access_token
        void client.from('audit_logs').insert({ actor_id: session.user.id, action: 'LOGIN', resource: 'Account', status: 'Success' })
      }
      void load()
    })
    return () => listener.subscription.unsubscribe()
  }, [])
  if (!ready) return <div className="loading">Opening DataGuard…</div>
  if (passwordRecovery) return <ResetPasswordScreen onComplete={() => setPasswordRecovery(false)} />
  if (!user) return <AuthScreen />
  return <App userId={user.id} userName={user.name} userEmail={user.email} initialIsAdmin={user.admin} onLogout={() => supabase?.auth.signOut()} />
}
createRoot(document.getElementById('root')!).render(<AppRoot />)
